#include "weather.hpp"
namespace echodrive {
WeatherSystem::WeatherSystem(){set(Weather::Clear);}
void WeatherSystem::set(Weather w){state_.type=w;state_.slippery=(w==Weather::Rain||w==Weather::Storm||w==Weather::Snow||w==Weather::Ice);switch(w){case Weather::Clear:state_.temperature=24;state_.wind=8;state_.humidity=40;break;case Weather::Rain:state_.temperature=18;state_.wind=20;state_.humidity=82;break;case Weather::Storm:state_.temperature=16;state_.wind=70;state_.humidity=88;break;case Weather::Wind:state_.temperature=21;state_.wind=85;state_.humidity=35;break;case Weather::HumidHeat:state_.temperature=39;state_.wind=12;state_.humidity=90;break;case Weather::Cold:state_.temperature=3;state_.wind=18;state_.humidity=55;break;case Weather::Snow:state_.temperature=-3;state_.wind=24;state_.humidity=80;break;case Weather::Ice:state_.temperature=-8;state_.wind=10;state_.humidity=65;break;case Weather::Desert:state_.temperature=43;state_.wind=32;state_.humidity=12;break;case Weather::Mountain:state_.temperature=8;state_.wind=48;state_.humidity=60;break;case Weather::Farm:state_.temperature=23;state_.wind=14;state_.humidity=58;break;}}
void WeatherSystem::cycle(){index_=(index_+1)%11;set(static_cast<Weather>(index_));}
std::string WeatherSystem::name(bool ar)const{static const char* a[]={"صحو","مطر","عاصفة ورعد","رياح قوية","حرارة ورطوبة مرتفعة","برد","ثلج","جليد","صحراء","جبال","منطقة زراعية"};static const char* e[]={"Clear","Rain","Storm and thunder","Strong wind","Hot and humid","Cold","Snow","Ice","Desert","Mountain","Farm"};return ar?a[(int)state_.type]:e[(int)state_.type];}
std::string WeatherSystem::advisory(bool ar)const{if(state_.slippery)return ar?"الطريق زلق، خفف السرعة":"Road is slippery, reduce speed";if(state_.type==Weather::Storm||state_.type==Weather::Wind)return ar?"رياح قوية، انتبه للمركبات":"Strong wind, watch nearby vehicles";if(state_.type==Weather::Desert)return ar?"منطقة صحراوية، الرؤية قد تنخفض":"Desert area, visibility may drop";return ar?"الظروف مستقرة":"Conditions are stable";}
std::string WeatherSystem::ambiencePath()const{static const char* p[]={"assets/audio/weather/clear.ogg","assets/audio/weather/rain.ogg","assets/audio/weather/storm.ogg","assets/audio/weather/wind.ogg","assets/audio/weather/humid.ogg","assets/audio/weather/cold.ogg","assets/audio/weather/snow.ogg","assets/audio/weather/ice.ogg","assets/audio/weather/desert.ogg","assets/audio/weather/mountain.ogg","assets/audio/weather/farm.ogg"};return p[(int)state_.type];}
}
